UPDATE profiles SET purpose='食事・お茶から', marital='既婚', children='あり（同居）', job='会社員', income='600〜800万円', education='大学卒', height=156, body_type='スリム', drinking='飲まない', smoking='吸わない', holiday='土日', avail='wd_night,we_day,we_night', bio='はじめまして。日々の生活の中でふと素の自分に戻れる時間を大切にしたくて登録しました。普段は仕事と家庭で慌ただしいですが、だからこそ肩の力を抜いて他愛もない話ができる方と出会えたら嬉しいです。まずは文章のやり取りから、少しずつ距離を縮められたらと思います。' WHERE user_id='u_sample1' AND gender='female';
UPDATE profiles SET purpose='まずは友達から', marital='既婚', children='あり（別居）', job='看護師', income='800〜1000万円', education='専門・短大卒', height=158, body_type='やや細め', drinking='ときどき飲む', smoking='吸わない', holiday='平日', avail='we_day,we_night', bio='静かなカフェでゆっくりお茶を飲みながら、好きな本や映画の話をする時間が好きです。派手なことより穏やかで心地よい距離感を何より大切にしたいタイプ。同じような価値観の方と、焦らず関係を育てていけたら幸いです。' WHERE user_id='u_sample3' AND gender='female';
UPDATE profiles SET purpose='気軽な関係', marital='既婚', children='なし', job='事務', income='400〜600万円', education='大学卒', height=160, body_type='普通', drinking='よく飲む', smoking='ときどき吸う', holiday='不定期', avail='wd_day,wd_evening', bio='休みの日は美味しいものを食べに出かけたりドライブをしてリフレッシュしています。一緒にいて自然体でいられる、聞き上手な方だと話が弾みそうです。まずは気軽にメッセージをいただけたら嬉しいです。' WHERE user_id='u_sample5' AND gender='female';
